const s = $json;
const NL = String.fromCharCode(10);
const esGuion = s.kind === 'script';
const label = s.cfg.context_label || 'Matemáticas de Grado Superior de la Comunidad Valenciana';
const officialLabel = s.cfg.official_label || 'Generalitat Valenciana (DOGV)';
const base = 'Eres el AGENTE REVISOR de AccesoPro, plataforma que prepara a adultos para las pruebas de acceso. Tu trabajo es impedir que se publique contenido con errores: un vídeo con un error de temario hace más daño que no publicarlo. Compruebas cada pieza contra el TEMARIO OFICIAL (' + officialLabel + ': fuente de autoridad; lista los saberes básicos y criterios de evaluación) y contra el temario de AccesoPro. El temario oficial no trae fórmulas ni ejemplos: para la corrección matemática usa matemáticas estándar y recalcula tú mismo. Sé estricto y literal; no revises el estilo, solo la corrección. RECHAZA si hay cualquiera de estos problemas: (a) un error matemático o de cálculo: recalcula TODAS las operaciones y comprueba cada resultado; (b) una regla o propiedad enunciada de forma incorrecta o tan incompleta o absoluta que lleve a error (por ejemplo, una afirmación del tipo siempre o nunca que tenga una excepción); (c) un dato, cifra, norma o afirmación inventada o que no puedas respaldar con el temario oficial, el temario de AccesoPro o matemáticas estándar; (d) contenido fuera de los saberes básicos de ' + label + '. Aprueba únicamente si no encuentras ningún problema. Cita siempre el fragmento exacto que falla.';
const extraClip = ' ADEMÁS, esta pieza es un fragmento de una clase hablada: ignora muletillas y frases a medias, pero marca cualquier error conceptual o de cálculo que no se corrija dentro del propio fragmento. Valora también si el clip se entiende SIN el resto de la clase: pon se_entiende_sola en false si empieza a mitad de idea o de frase, si depende de algo dicho antes (por ejemplo, referencias a lo de antes, al ejercicio anterior o a la pantalla sin explicarlas), o si termina sin cerrar la idea; en motivo_contexto explica por qué.';
const system = base + (esGuion ? '' : extraClip);
let content;
if (esGuion) {
  content = 'TIPO DE PIEZA: guion de vídeo corto (30-60 s).' + NL + 'GANCHO: ' + s.script.gancho + NL + 'EXPLICACIÓN: ' + s.script.explicacion + NL + 'CIERRE: ' + s.script.cierre;
} else {
  content = 'TIPO DE PIEZA: clip recortado de una clase en directo (' + (s.clip.type || 'momento') + ', ' + Math.round(s.clip.end - s.clip.start) + ' s). Transcripción literal:' + NL + s.text;
}
const user = 'TEMARIO OFICIAL (' + officialLabel + '):' + NL + s.ctx.official + NL + NL + 'TEMARIO ACCESOPRO DEL TEMA:' + NL + s.ctx.temario + NL + NL + 'PIEZA A REVISAR:' + NL + content + NL + NL + 'Devuelve tu veredicto en el formato JSON indicado.';
const arr = (items) => ({ type: 'array', items: items });
const str = { type: 'string' };
const schema = {
  type: 'object',
  additionalProperties: false,
  required: ['aprobado', 'motivo', 'calculos', 'errores', 'datos_no_respaldados', 'fuera_de_temario', 'se_entiende_sola', 'motivo_contexto'],
  properties: {
    aprobado: { type: 'boolean' },
    motivo: str,
    calculos: arr({ type: 'object', additionalProperties: false, required: ['operacion', 'resultado_correcto', 'correcto_en_la_pieza'], properties: { operacion: str, resultado_correcto: str, correcto_en_la_pieza: { type: 'boolean' } } }),
    errores: arr({ type: 'object', additionalProperties: false, required: ['fragmento', 'problema', 'correccion'], properties: { fragmento: str, problema: str, correccion: str } }),
    datos_no_respaldados: arr(str),
    fuera_de_temario: { type: 'boolean' },
    se_entiende_sola: { type: 'boolean' },
    motivo_contexto: str
  }
};
const req = {
  model: s.cfg.reviewer_model,
  messages: [{ role: 'system', content: system }, { role: 'user', content: user }],
  response_format: { type: 'json_schema', json_schema: { name: 'revision', strict: true, schema: schema } }
};
if (String(s.cfg.reviewer_model).indexOf('gpt-4') === 0) req.temperature = 0;
return { json: Object.assign({}, s, { req: req }) };

const s = $('Construir prompt de revisión').item.json;
const r = $json;
let rev;
try {
  rev = JSON.parse(r.choices[0].message.content);
} catch (e) {
  throw new Error('Respuesta del revisor no válida: ' + e.message);
}
const u = r.usage || {};
const cost = ((u.prompt_tokens || 0) * s.cfg.price_reviewer_in + (u.completion_tokens || 0) * s.cfg.price_reviewer_out) / 1000000;
const errores = rev.errores || [];
const malCalc = (rev.calculos || []).filter((c) => c.correcto_en_la_pieza === false);
const noRespaldados = rev.datos_no_respaldados || [];
const esClip = s.kind === 'clip';
const sinContexto = esClip && rev.se_entiende_sola !== true;
const approved = rev.aprobado === true && errores.length === 0 && malCalc.length === 0 && noRespaldados.length === 0 && rev.fuera_de_temario !== true && !sinContexto;
const out = Object.assign({}, s);
delete out.req;
const costs = s.costs || { llm: 0, voice: 0, stt: 0 };
out.costs = { llm: (costs.llm || 0) + cost, voice: costs.voice || 0, stt: costs.stt || 0 };
out.review = rev;
out.approved = approved;
let reason = approved ? 'Aprobado' : (rev.motivo || '');
if (!approved && errores.length) reason += ' | Errores: ' + errores.map((e) => '"' + e.fragmento + '" -> ' + e.problema + ' (correcto: ' + e.correccion + ')').join(' ; ');
if (!approved && noRespaldados.length) reason += ' | No respaldado: ' + noRespaldados.join(' ; ');
if (!approved && sinContexto) reason += ' | No se entiende sin el resto de la clase: ' + (rev.motivo_contexto || '');
out.review_reason = reason;
out.reviews = (s.reviews || []).concat([{ aprobado: approved, motivo: reason }]);
return { json: out };
